// src/components/signMaintenance/dimLetterPaintCalculator.jsx
var num8 = (v, d = 0) => {
  const n = parseFloat(v);
  return Number.isFinite(n) ? n : d;
};
var UNIT_FACTORS = { oz: 1 / 128, pint: 1 / 8, quart: 1 / 4, liter: 1 / 3.78541, gallon: 1 };
var costPerGallon = (cost, unit) => {
  const c = num8(cost);
  const f = UNIT_FACTORS[unit] || 1;
  if (!f) return 0;
  return c / f;
};
var mixedPaintCostPerSqft = (s) => {
  const paintG = costPerGallon(s.paint_cost_per_unit, s.paint_unit);
  const hardG = costPerGallon(s.hardener_cost_per_unit, s.hardener_unit);
  const redG = costPerGallon(s.reducer_cost_per_unit, s.reducer_unit);
  const pR = num8(s.paint_mix_ratio), hR = num8(s.hardener_mix_ratio), rR = num8(s.reducer_mix_ratio);
  const parts2 = pR + hR + rR;
  if (!parts2) return 0;
  const costPerGalMixed = (paintG * pR + hardG * hR + redG * rR) / parts2;
  const coverage = num8(s.mixed_paint_coverage_sqft_per_gallon, 350) || 350;
  return costPerGalMixed / coverage;
};
var computeDimLetterPaint = (cfg, settings) => {
  const dl = cfg?.dim_letter_paint;
  if (!dl?.enabled) return null;
  const qty2 = Math.max(0, num8(dl.qty));
  if (qty2 <= 0) return null;
  const hIn = Math.max(0, num8(dl.avg_height_in));
  const tIn = Math.max(0, num8(dl.thickness_in));
  if (hIn <= 0) return null;
  const perimFactor = num8(settings.letter_perimeter_factor, 3.5) || 3.5;
  const FACE_FACTOR = 0.55;
  const facePerLetterIn2 = hIn * hIn * FACE_FACTOR;
  const returnsPerLetterIn2 = hIn * perimFactor * tIn;
  const SQIN_PER_SQFT = 144;
  const letters_face_sqft = facePerLetterIn2 * qty2 / SQIN_PER_SQFT;
  const letters_returns_sqft = returnsPerLetterIn2 * qty2 / SQIN_PER_SQFT;
  const letters_total_sqft = letters_face_sqft + letters_returns_sqft;
  const liquid$PerSqft = mixedPaintCostPerSqft(settings);
  const wasteMult = num8(settings.paint_waste_multiplier, 1.25) || 1.25;
  const letters_paint_cost = letters_total_sqft * liquid$PerSqft * wasteMult;
  const coverage = num8(settings.mixed_paint_coverage_sqft_per_gallon, 350) || 350;
  const letters_gallons = letters_total_sqft * wasteMult / coverage;
  const basePerSqft = num8(settings.base_labor_hours_per_sqft, 0.05);
  let prepMult = num8(settings.lettering_normal_prep_multiplier, 1) || 1;
  if (hIn <= 4) prepMult = num8(settings.lettering_extra_small_prep_multiplier, 1.5);
  else if (hIn <= 8) prepMult = num8(settings.lettering_small_prep_multiplier, 1.3);
  else if (hIn <= 12) prepMult = num8(settings.lettering_normal_prep_multiplier, 1);
  else if (hIn <= 20) prepMult = num8(settings.lettering_medium_prep_multiplier, 0.9);
  else if (hIn <= 30) prepMult = num8(settings.lettering_large_prep_multiplier, 0.8);
  else prepMult = num8(settings.lettering_extra_large_prep_multiplier, 0.7);
  const letters_labor_hours = letters_total_sqft * basePerSqft * prepMult;
  const usingMask = dl.second_color_mask === "paint_mask";
  let mask_sqft = 0, mask_material_cost = 0, mask_machine_cost = 0;
  let mask_weed_labor_cost = 0, mask_apply_labor_cost = 0, mask_labor_hours = 0;
  if (usingMask) {
    mask_sqft = letters_face_sqft;
    const matRate = num8(settings.paint_mask_rate_per_sqft);
    const machineRate = num8(settings.paint_mask_machine_cutting_rate_per_sqft);
    const weedRate = num8(settings.paint_mask_cutting_labor_rate_per_sqft);
    const applyRate = num8(settings.paint_mask_application_labor_rate_per_sqft);
    const laborRate = num8(settings.default_labor_rate, 60) || 60;
    mask_material_cost = mask_sqft * matRate;
    mask_machine_cost = mask_sqft * machineRate;
    mask_weed_labor_cost = mask_sqft * weedRate;
    mask_apply_labor_cost = mask_sqft * applyRate;
    const mask_labor_cost = mask_weed_labor_cost + mask_apply_labor_cost;
    mask_labor_hours = laborRate > 0 ? mask_labor_cost / laborRate : 0;
    const secondColorExtraPaint = letters_face_sqft * liquid$PerSqft * wasteMult;
    return finalize({
      letters_face_sqft,
      letters_returns_sqft,
      letters_total_sqft,
      letters_gallons: letters_gallons + letters_face_sqft * wasteMult / coverage,
      letters_paint_cost: letters_paint_cost + secondColorExtraPaint,
      mask_sqft,
      mask_material_cost,
      mask_machine_cost,
      mask_weed_labor_cost,
      mask_apply_labor_cost,
      mask_labor_hours,
      letters_labor_hours
    });
  }
  return finalize({
    letters_face_sqft,
    letters_returns_sqft,
    letters_total_sqft,
    letters_gallons,
    letters_paint_cost,
    mask_sqft: 0,
    mask_material_cost: 0,
    mask_machine_cost: 0,
    mask_weed_labor_cost: 0,
    mask_apply_labor_cost: 0,
    mask_labor_hours: 0,
    letters_labor_hours
  });
};
var finalize = (r2) => {
  const mask_total_cost = r2.mask_material_cost + r2.mask_machine_cost + r2.mask_weed_labor_cost + r2.mask_apply_labor_cost;
  const letters_total_added_cost = r2.letters_paint_cost + mask_total_cost;
  return { ...r2, mask_total_cost, letters_total_added_cost };
};

